package com.example.des;

import com.badlogic.gdx.ApplicationAdapter;
import com.badlogic.gdx.Gdx;

import java.nio.file.Path;

/**
 * libGDX {@link com.badlogic.gdx.ApplicationListener} that drives the whole
 * simulation from within {@link #create()}, then exits the headless app.
 * No OpenGL / Gdx.gl* calls are made anywhere; this listener is pure logic.
 */
public class SimulationListener extends ApplicationAdapter {

    private final Path inputPath;
    private final Path outputPath;

    public SimulationListener(Path inputPath, Path outputPath) {
        this.inputPath = inputPath;
        this.outputPath = outputPath;
    }

    @Override
    public void create() {
        int exitCode = 0;
        try {
            Simulator.run(inputPath, outputPath);
        } catch (Exception e) {
            e.printStackTrace();
            exitCode = 1;
        }

        // Headless app is configured with a negative render interval, so render()
        // is never invoked and the main loop thread will terminate right after
        // create() returns. We still call exit() defensively.
        Gdx.app.exit();

        if (exitCode != 0) {
            System.exit(exitCode);
        }
    }
}

package com.example.des;

import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;

import java.nio.file.Path;
import java.nio.file.Paths;

/**
 * Entry point. Boots libGDX's headless backend (no OpenGL, no window) and runs
 * the discrete-event factory simulation described by the given scenario file,
 * writing the deterministic result to the given output file.
 *
 * Usage:
 *   --input=&lt;path&gt; --output=&lt;path&gt;   (order of the two arguments does not matter)
 */
public class DesLauncher {

    public static void main(String[] args) {
        String inputArg = null;
        String outputArg = null;

        for (String arg : args) {
            if (arg.startsWith("--input=")) {
                inputArg = arg.substring("--input=".length());
            } else if (arg.startsWith("--output=")) {
                outputArg = arg.substring("--output=".length());
            }
        }

        if (inputArg == null || outputArg == null) {
            System.err.println("Usage: --input=<path> --output=<path>");
            System.exit(2);
            return;
        }

        Path inputPath = Paths.get(inputArg);
        Path outputPath = Paths.get(outputArg);

        HeadlessApplicationConfiguration config = new HeadlessApplicationConfiguration();
        // Negative: never invoke render(); we do all work once in create().
        config.updatesPerSecond = -1;

        new HeadlessApplication(new SimulationListener(inputPath, outputPath), config);
    }
}
